tags.gen_ai.tool.definitions:
[
  {
    "type": "function",
    "name": "list_requirements",
    "description": "Listet die kanonischen Requirements der Baseline (id, title, status, sourceItemIds).",
    "parameters": {
      "type": "object",
      "properties": {
        "limit": {
          "type": "integer",
          "default": 100
        }
      }
    }
  },
  {
    "type": "function",
    "name": "search_requirements",
    "description": "Sucht in Requirements nach Stichworten (id/title/text).",
    "parameters": {
      "type": "object",
      "properties": {
        "query": {
          "type": "string"
        },
        "limit": {
          "type": "integer",
          "default": 30
        }
      },
      "required": [
        "query"
      ]
    }
  },
  {
    "type": "function",
    "name": "get_requirement",
    "description": "Liest ein Requirement vollstaendig (Text, Status, Quellen, Metadaten).",
    "parameters": {
      "type": "object",
      "properties": {
        "requirementId": {
          "type": "string"
        }
      },
      "required": [
        "requirementId"
      ]
    }
  },
  {
    "type": "function",
    "name": "get_related_requirements",
    "description": "Liefert die AUTHORED verwandten Requirements (L3/L4-Relationen) fuer ein Requirement.",
    "parameters": {
      "type": "object",
      "properties": {
        "requirementId": {
          "type": "string"
        }
      },
      "required": [
        "requirementId"
      ]
    }
  },
  {
    "type": "function",
    "name": "check_clusters",
    "description": "Prueft Cluster deterministisch (Coverage: jedes aktive Requirement genau einmal core). Vor dem Speichern nutzen.",
    "parameters": {
      "type": "object",
      "properties": {
        "clusters": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "clusterId": {
                "type": "string"
              },
              "identityKey": {
                "type": "string"
              },
              "label": {
                "type": "string"
              },
              "coreRequirementIds": {
                "type": "array",
                "items": {
                  "type": "string"
                }
              },
              "crossCuttingRequirementIds": {
                "type": "array",
                "items": {
                  "type": "string"
                }
              },
              "rationale": {
                "type": [
                  "string",
                  "null"
                ]
              }
            },
            "required": [
              "clusterId",
              "identityKey",
              "label",
              "coreRequirementIds",
              "crossCuttingRequirementIds",
              "rationale"
            ]
          }
        }
      },
      "required": [
        "clusters"
      ]
