    "parameters": {
      "type": "object",
      "properties": {
        "clusters": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "clusterId": {
                "type": "string"
              },
              "identityKey": {
                "type": "string"
              },
              "label": {
                "type": "string"
              },
              "coreRequirementIds": {
                "type": "array",
                "items": {
                  "type": "string"
                }
              },
              "crossCuttingRequirementIds": {
                "type": "array",
                "items": {
                  "type": "string"
