tags.gen_ai.tool.definitions:
[
  {
    "type": "function",
    "name": "get_requirement",
    "description": "Liest ein Requirement vollstaendig, um die Cluster-Zuordnung fachlich zu pruefen.",
    "parameters": {
      "type": "object",
      "properties": {
        "requirementId": {
          "type": "string"
        }
      },
      "required": [
        "requirementId"
      ]
    }
  },
  {
    "type": "function",
    "name": "save_review",
    "description": "Speichert Review-Feedback: findings (Diagnose) UND operations (konkrete, anwendbare Fixes). Genau einmal am Ende.",
    "parameters": {
      "type": "object",
      "properties": {
        "verdict": {
          "type": "string"
        },
        "summary": {
          "type": "string"
        },
        "findings": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "clusterId": {
                "type": [
                  "string",
                  "null"
                ]
              },
              "kind": {
                "type": "string"
              },
              "severity": {
                "type": "string"
              },
              "message": {
                "type": "string"
              }
            },
            "required": [
              "clusterId",
              "kind",
              "severity",
              "message"
            ]
          }
        },
        "operations": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "opId": {
                "type": "string"
              },
              "kind": {
                "type": "string"
              },
              "rationale": {
                "type": [
                  "string",
                  "null"
                ]
              },
              "requirementId": {
                "type": [
                  "string",
                  "null"
                ]
              },
              "fromClusterId": {
                "type": [
                  "string",
                  "null"
                ]
              },
              "toClusterId": {
                "type": [
                  "string",
                  "null"
                ]
              },
              "newClusterId": {
                "type": [
                  "string",
                  "null"
                ]
              },
              "label": {
                "type": [
                  "string",
                  "null"
                ]
              },
              "identityKey": {
                "type": [
                  "string",
                  "null"
                ]
              },
              "coreRequirementIds": {
                "type": "array",
                "items": {
                  "type": "string"
                }
              }
            },
            "required": [
              "opId",
              "kind",
              "rationale"
            ]
          }
        }
      },
      "required": [
        "verdict",
        "summary",
        "findings",
        "operations"
      ]
    }
  }
]

