        "response": "{\n  \"requirementId\": \"REQ-07\",\n  \"title\": \"Nach dem Login soll auf jeder Seite eine Appbar vorhanden sein, die mindestens R...\",\n  \"text\": \"Nach dem Login soll auf jeder Seite eine Appbar vorhanden sein, die mindestens R\\u00FCcknavigation und Logout erm\\u00F6glicht. Eine Einstellungsfunktion in der Appbar ist vorgesehen, aber noch nicht ausgearbeitet und soll weiter gekl\\u00E4rt werden.\",\n  \"status\": \"active\",\n  \"sourceItemIds\": [\n    \"REQ-07\"\n  ],\n  \"originSummary\": \"Extracted\",\n  \"version\": 1,\n  \"metadata\": {\n    \"artifactVersion\": \"1\",\n    \"producerModel\": \"openai/gpt-5.4\"\n  }\n}"
